INSERT INTO traits (id, clause, embedding_id) VALUES
  ('e543e38b-7e07-4800-85ec-d24e183fa3df'::uuid, 'Was completed in 1889 as the centerpiece for a world''s fair', '41e7247b-7cdc-4c90-949c-23711ba9fc8b'::uuid),
  ('a6fdac61-ae5e-4206-a32e-63eaf14b99c5'::uuid, 'Stands 330 meters tall including its antenna', '46325b9b-6594-4bbb-82c3-5090488c017c'::uuid),
  ('bcf07187-b3df-4f67-871e-2b88a93aac3f'::uuid, 'Originally constructed as a temporary structure with a 20-year permit', '3eb54831-7c57-4d0c-91ee-b14c86b3cb33'::uuid),
  ('d75fbb9a-bc24-4b7a-8b95-91a18d9a9bd4'::uuid, 'Was the tallest man-made structure in the world until 1930', '3328293b-802d-4212-955d-029acdb38bc9'::uuid),
  ('2e00dd95-185f-4485-9294-0204d6fac1fb'::uuid, 'Built primarily from wrought iron using over 18,000 individual parts', 'eb61ee61-2b76-42d5-bf69-4476a74861fc'::uuid),
  ('e42d3c6a-10f2-42fc-aaa2-faae4d636d4e'::uuid, 'Features a lattice design to reduce wind resistance and material use', 'b23bc1a9-f8c8-4204-a896-6d10233d0c59'::uuid),
  ('9c7ffc9c-b71a-4c53-81f0-00da2ac70abe'::uuid, 'Designed by engineers Maurice Koechlin and Émile Nouguier, with contributions from Stephen Sauvestre', 'f4316a7f-6778-4993-b415-ce82f8222183'::uuid),
  ('70ae2ecf-51f1-4df0-9f78-6f41dd29bea4'::uuid, 'Named after Gustave Eiffel, whose company led its construction despite not being the sole designer', '1e04c17b-7a06-4926-9aaa-a0817432a21d'::uuid),
  ('4e44f118-ecf7-4970-8996-8fff163fed66'::uuid, 'Served as a radio transmission tower starting in the early 20th century', 'f54f0c3e-81e5-4d57-8103-81d84d7a0e31'::uuid),
  ('369ab223-db4e-4a27-91c7-dd334011fecb'::uuid, 'Broadcasts FM radio and DVB-T digital television signals across its region', '6c634b27-3b37-4744-8a0f-33affe9bd448'::uuid),
  ('75043f4b-ac0b-4cf5-a8fd-07a5a98d7404'::uuid, 'Receives approximately 7 million visitors annually, making it one of the most visited paid monuments globally', '59daf8b9-3945-4115-b35e-c0c2e100c47a'::uuid),
  ('dead517c-3c27-4944-b051-4d5cfcd8e167'::uuid, 'Has a pyramidal lattice shape with four arched legs meeting at a central spire', 'bdf775f2-7b63-4b5c-adb9-e84e8c5c4685'::uuid),
  ('bef7e769-c607-45fa-9933-5bc574d1e715'::uuid, 'Painted in three shades of brown, darkest at the base, to blend with the skyline when viewed from below', '97ccefd1-b23a-4b67-a0bb-1769f79225d9'::uuid),
  ('86946410-bbcd-4bf3-a45e-4542c87f0c40'::uuid, 'Underwent major restoration and repainting every seven years since its construction', '2284764a-e312-4a98-be02-0e13ede67822'::uuid),
  ('26a3e2fb-1536-41ab-adbb-60c04c646dc2'::uuid, 'Designated as a protected historical monument in France in 1964', '6d3f82eb-3fec-489d-8f54-57cd658083a6'::uuid),
  ('946d90dc-37d9-4c00-bed3-bd3f64d3b74a'::uuid, 'Uses over 60 tons of paint during each full repaint to prevent rusting', '314af052-5ae0-438f-8e62-633ea705acd0'::uuid),
  ('d79d184c-ea1c-4fb9-9b03-6ca38e056c15'::uuid, 'Originally criticized by many artists and intellectuals as an eyesore upon completion', '3d3fef2c-e7e3-4f14-913a-675b5ad2985a'::uuid),
